CHANGELOG = '## [0.261.0] - every opening\'s landing is lit to read from above\n\n**The walker\'s walk of cold run 9383** (the factory\'s `docs/findings/walk_2026-10-23_deli/`, finding 1), of a stair\nopening onto deli_a03\'s basement: "this shouldn\'t look pitch black" -- and the rule: "you should be able to see into\nholes to know you can go forward into them". The basement is moody by rule -- bare bulbs, dark corners -- and the\nplace the stairs come down into it read luma p50 10 from its own station, against the stairwell above at 74.\n\n### Added\n- **`opening_landings(spec)`**: where every opening into a storey lands -- a stair\'s lower end\n  (`stairwell.stair_endpoints`), the floor under each hole in a slab that is not a stair\'s own (authored holes, floor\n  holes, hatches), a ladder\'s base -- one entry a place.\n- **A moody room lights its landings** (`derive_light_anchors(..., landings=)`, `build_light_manifest(...,\n  landings=)`, passed by the build): a fluorescent over each landing inside it -- the lamp an ordinary room is lit by\n  -- and, where a hole is over the landing, hung `_LANDING_OFF_HOLE` (0.6 m) past the hole\'s edge on the side nearest\n  the room\'s middle, then kept off the partitions as every lamp is (`_row_runs`). Each carries `landing` (its kind),\n  and they come last with the spills, so every anchor before them keeps its id and its place. A moody room keeps its\n  bulbs; an ordinary room, already lit by its rows, gets none. A hole that is a ladder\'s or a stair\'s own cut\n  (`_own_hole`: the builder cuts both into the slabs the lights are derived from) is that opening, not a second\n  one -- the first build of this change lit deli_a03\'s basement corridor twice at one point, its ladder and the\n  ladder\'s own hole, and 153 lamps went into 40 buildings where the openings asked fewer. The count the library\n  takes is the rebuilt light records\' (the factory\'s `patches/dc_landing_lights/landing_census.out.txt`).\n\n### Tests\n- `test_landing_lights.py` (new): every opening of deli_a03 lands once; THE TEST THAT MATTERS -- its basement\'s stair\n  foot and ladder base are lit, the rooms above get nothing, and every anchor before is the same and in order; a\n  landing under a hole hangs its lamp beside the hole; a spec cut the way the builder cuts it lands exactly as the\n  library spec does. On 0.260.0 the four fail on the new names.\n  `test_lights_partitions.py` pins the derivation\'s report key for key: it gains `landing_lights` (the first run of\n  this change applied it without, and the paired suites caught it -- one new failure, the pinned dict).\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.260.0', 'Deli Counter 0.261.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
